def _load_completion_union(
    paths: list[str],
    accepted: dict[str, dict[str, Any]],
    history: dict[str, list[dict[str, Any]]],
) -> dict[str, dict[str, Any]]:
    # The union of completion records across the explicit ledger and the
    # ledgers discovered beside the snapshots, keyed by job id. Ledgers
    # are fully validated against the same acceptance and supply
    # snapshots; a malformed completion ledger raises just like any
    # other malformed business ledger.
    from . import completion as _completion
    records: dict[str, dict[str, Any]] = {}
    for real in paths:
        ledger_records, _ids, _events, raw = \
            _completion._load_completion_ledger(real, accepted, history)
        if raw is None:
            raise FileNotFoundError(
                f"completion ledger {real!r} does not exist")
        for record in ledger_records.values():
            records.setdefault(record["job_id"], record)
    return records


def _completion_capacity_envelope(
    trades: dict[str, dict[str, Any]],
    completed: dict[str, dict[str, Any]],
    history: dict[str, list[dict[str, Any]]],
) -> None:
    # Replay every capacity-changing event per exact resource version:
    # a trade books its work at its evaluation moment, and a completion
    # releases the work again at its completion moment -- but only while
    # the completed job still occupied its traded version (a migrated
    # job left the source through its settled migration, which this
    # ledger never tracks). Releases are applied before bookings at the
    # same moment, since "not later than" already frees the capacity.
    # Capacity must never be oversold at any booking moment.
    def capacity_of(slot: tuple[str, int]) -> int:
        resource_id, version = slot
        return history[resource_id][version - 1]["capacity"]

    events: dict[tuple[str, int], list[tuple[int, int, int, str]]] = {}
    for job_id, trade in trades.items():
        slot = (trade["resource_id"], trade["version"])
        events.setdefault(slot, []).append(
            (trade["at"], 1, trade["work"], job_id))
    for job_id, record in completed.items():
        trade = trades.get(job_id)
        if trade is None:
            continue
        slot = (trade["resource_id"], trade["version"])
        current = record["current"]
        if (current["resource_id"], current["version"]) != slot:
            # The job migrated away from its traded version; its source
            # release is already accounted by the settlement/intent
            # layers, never by this trades-only invariant.
            continue
        events.setdefault(slot, []).append(
            (record["at"], 0, trade["work"], job_id))
    for slot, slot_events in events.items():
        running = 0
        # Releases (kind 0) before bookings (kind 1) at the same moment.
        for at, kind, work, _job_id in sorted(
                slot_events, key=lambda event: (event[0], event[1])):
            if kind == 0:
                running -= work
                if running < 0:
                    raise ValueError(
                        "completion releases capacity a trade never booked")
            else:
                running += work
                if running > capacity_of(slot):
                    raise ValueError(
                        "ledger oversells a published resource version")


